-- Тексты FAQ под онлайн-оплату. Каждый UPDATE срабатывает, только если ответ всё ещё дословно равен
-- исходному из 0002_faq_seed.sql: ответы, которые владелец уже поправил в админке, не перезаписываются.
UPDATE "faq_items" SET "answer" = 'Оплата онлайн на сайте — картой, по СБП, SberPay или T-Pay. Билет и кассовый чек приходят на почту. Отменить или перенести без потерь можно за 24 часа до начала, позже — возврат 50%. Для отмены напишите или позвоните нам.' WHERE "question" = 'Как оплатить и можно ли отменить бронь?' AND "answer" = 'После заявки мы согласуем детали и присылаем ссылку на оплату. Отменить или перенести бронь без потерь можно за 24 часа до начала. При отмене позже — возврат 50%.';--> statement-breakpoint
UPDATE "faq_items" SET "answer" = 'Для семей от 4 человек и для двух экскурсий в один визит есть специальные условия — напишите нам, подберём вариант.' WHERE "question" = 'Есть ли скидки для больших семей?' AND "answer" = 'Да, при бронировании от 4 человек — семейный тариф. Для двух и более экскурсий в один визит — «маршрут выходного дня» со скидкой 10%. Пишите — подберём вариант.';--> statement-breakpoint
UPDATE "faq_items" SET "answer" = 'Да. Любая экскурсия из каталога может пройти в формате «только ваша семья»: выбираете удобное время, темп и акценты. Стоимость и детали — по запросу: напишите или позвоните нам.' WHERE "question" = 'Проводите индивидуальные экскурсии?' AND "answer" = 'Да. Любая экскурсия из каталога может пройти в формате «только ваша семья»: выбираете удобное время, темп и акценты. Стоимость и детали — по запросу через форму или в личном сообщении.';
